mapper.select:
SELECT * FROM ( SELECT #{TOT_CNT} AS TOT_CNT , ROWNUM AS SEQ , T.* FROM ( SELECT /* isry.itgcm.casemng.caseunity.CaseTrmnMapper.selectCaseTrmnAprvList(사례종결승인목록조회) */ ROW_NUMBER() OVER(PARTITION BY T2.CASE_MNG_NO, T2.CASE_MNG_ODRNO ORDER BY T2.FRST_REG_DT DESC) AS RM , T1.TRPR_INFO_NO AS TRPR_INFO_NO -- 대상자정보번호(TR) , C##RG.DEC_B64(T1.TRPR_NM_ENCPT) AS TRPR_NM_ENCPT , T1.TRPR_BRTH_YMD AS TRPR_BRTH_YMD -- 대상자출생일자 , T1.SXDC_SE_CD AS SXDC_SE_CD -- 성별구분코드 , T2.CASE_MNG_NO AS CASE_MNG_NO -- 사례관리번호(CS) , T2.UNT_TASKWK_SE_CD AS UNT_TASKWK_SE_CD -- 단위업무구분코드 , T2.CASE_MNG_ODRNO AS CASE_MNG_ODRNO -- 사례관리차수 , T2.CASE_PRGRS_STTS_SE_CD AS CASE_PRGRS_STTS_SE_CD -- 사례진행상태구분코드 , T3.CASE_TRMN_NO AS CASE_TRMN_NO -- 사례종결번호(CT) , T3.TRMN_APLY_YMD AS TRMN_APLY_YMD -- 종결신청일자 , T3.TRMN_SRNG_YMD AS TRMN_SRNG_YMD -- 종결심사일자 , T3.TRMN_SRNG_RESULT_SE_CD AS TRMN_SRNG_RESULT_SE_CD -- 종결심사결과구분코드 , T3.CASE_TRMN_YMD AS CASE_TRMN_YMD -- 사례종결일자 , T3.TRMN_CS_SE_CD AS TRMN_CS_SE_CD -- 종결사유구분코드 , T3.TRMN_CS_SE_CD_ETC_CN AS TRMN_CS_SE_CD_ETC_CN -- 종결사유구분코드기타내용 , T3.GOAL_ACHIV_DGREE_SE_CD AS GOAL_ACHIV_DGREE_SE_CD -- 목표달성정도구분코드 , T3.GOAL_ACHIV_OUTC_CN AS GOAL_ACHIV_OUTC_CN -- 목표달성성과내용 , T3.CASE_TRMN_HR AS CASE_TRMN_HR -- 사례종결시간 , T3.ATFINO AS ATFINO -- 첨부파일번호 , T3.YNGBGS_CHNG_LAST_RESULT_CN AS YNGBGS_CHNG_LAST_RESULT_CN -- 청소년변화최종결과내용 , T3.MIND_MDCINE_DSCSN_CN AS MIND_MDCINE_DSCSN_CN -- 정신의학상담내용 , T3.PROBM_SLTN_SE_CD AS PROBM_SLTN_SE_CD -- 문제해결구분코드 , T3.MDSTRM_FAILR_CS_SE_CD AS MDSTRM_FAILR_CS_SE_CD -- 중도탈락사유구분코드 , T3.PIC_OPNN_CN AS PIC_OPNN_CN -- 담당자의견내용 , T3.PSTRTR_RESDN_SE_CD AS PSTRTR_RESDN_SE_CD -- 퇴소후거주구분코드 , T3.PSTRTR_SCHULW_SE_CD AS PSTRTR_SCHULW_SE_CD -- 퇴소후학업구분코드 , T3.PSTRTR_SLFRL_SE_CD AS PSTRTR_SLFRL_SE_CD -- 퇴소후자립구분코드 , T3.TRMN_SE_CD AS TRMN_SE_CD -- 종결구분코드 , T3.TRMN_AFTR_ZIP AS TRMN_AFTR_ZIP -- 종결이후우편번호 , T3.TRMN_AFTR_PST_ADDR AS TRMN_AFTR_PST_ADDR -- 종결이후우편주소 , T3.TRMN_AFTR_DADDR AS TRMN_AFTR_DADDR -- 종결이후상세주소 , T3.FRST_REG_DT AS FRST_REG_DT -- 최초등록일시 , T3.LAST_MDFCN_DT AS LAST_MDFCN_DT -- 최종수정일시 , T2.AFTFCT_MNG_YN AS AFTFCT_MNG_YN -- 사후관리여부 , T4.PIC_NO AS PIC_NO -- 심사자번호 , (SELECT C##RG.DEC_B64(FLNM_ENCPT) FROM SCA100 WHERE ENFSN_NO = T4.PIC_NO) AS PIC_NM_ENCPT -- 종결최종처리자(승인) , T4.PIC_INST_NO AS PIC_INST_NO -- 심사자기관번호 , (SELECT INST_NM FROM SAA000 WHERE INST_NO = T4.PIC_INST_NO) AS PIC_INST_NM -- 심사자기관명 , T4.REJDGE_TKCG_YN AS REJDGE_TKCG_YN -- 재심사담당여부 , T4.TRMN_SRNG_TKCG_YN AS TRMN_SRNG_TKCG_YN -- 종결심사담당여부 , (SELECT C##RG.DEC_B64(FLNM_ENCPT) FROM SCA100 WHERE ENFSN_NO = T5.CASE_PIC_NO) AS CASE_PIC_NM_ENCPT -- 사례담당자 , (SELECT INST_NM FROM SAA000 WHERE INST_NO = T5.PIC_INST_NO) AS CASE_PIC_INST_NM -- 사례담당자기관명 , T5.PIC_INST_NO AS CASE_PIC_INST_NO FROM SEA200 T1 /* 대상자정보 */ , SEB100 T2 /* 사례기본 */ , SEC100 T3 /* 사례종결 */ , SEC120 T4 /* 심사담당자 */ , SEB150 T5 WHERE 1 = 1 AND T1.TRPR_INFO_NO = T2.TRPR_INFO_NO AND T2.CASE_MNG_NO = T3.CASE_MNG_NO AND T2.CASE_MNG_ODRNO = T3.CASE_MNG_ODRNO AND T3.CASE_TRMN_NO = T4.CASE_TRMN_NO(+) AND T2.CASE_MNG_NO = T5.CASE_MNG_NO AND T2.CASE_MNG_ODRNO = T5.CASE_MNG_ODRNO AND T2.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND T2.CASE_PRGRS_STTS_SE_CD IN ('04','06','08','10') -- 종결, 사후관리, 사후종결, 재개입 AND T3.TRMN_SRNG_RESULT_SE_CD = '02' AND T4.TRMN_SRNG_TKCG_YN = 'Y'
) T WHERE 1 = 1 AND RM = 1 ) WHERE 1 = 1
AND SEQ >= #{START_IDX} AND SEQ <= #{LAST_IDX}

SELECT CASE_TRMN_YMD
FROM SEC100
WHERE CASE_TRMN_NO  = #{CASE_TRMN_NO}

mapper.update:
UPDATE SEC100
SET CASE_TRMN_YMD = #{CASE_TRMN_YMD}
WHERE CASE_TRMN_NO  = #{CASE_TRMN_NO}
